import{_ as a,c as e,o as l,af as t}from"./chunks/framework.BKeRpnBD.js";const h=JSON.parse('{"title":"周易常识","description":"周易常识，整理自 App 的免费易经学习文档。","frontmatter":{"title":"周易常识","description":"周易常识，整理自 App 的免费易经学习文档。"},"headers":[],"relativePath":"zh/articles/basics/index.md","filePath":"zh/articles/basics/index.md"}'),r={name:"zh/articles/basics/index.md"};function s(n,i,c,o,d,_){return l(),e("div",null,[...i[0]||(i[0]=[t('<h1 id="周易常识-简要" tabindex="-1">周易常识（简要） <a class="header-anchor" href="#周易常识-简要" aria-label="Permalink to “周易常识（简要）”">​</a></h1><ul><li>卦（hexagram）：六爻构成，上三爻为上卦，下三爻为下卦。</li><li>爻（line）：静爻，阴爻（断）/阳爻（连），用彩色线条，颜色依卦象属性（天/地/雷/风/水/火/山/泽）而定；老阴老阳为动爻，老阴后面以叉号（×）标示，老阳后面以圆圈（○）标示。</li><li>上下卦：六十四卦皆由上下二卦构成——上三爻为「上卦」（亦称外卦、用卦），下三爻为「下卦」（亦称内卦、体卦）。</li><li>当位（爻位的阴阳属性）：六爻自下而上为初、二、三、四、五、上。位性：一/三/五为阳位；二/四/上（六）为阴位。阳爻居阳位、阴爻居阴位，谓之「当位」「得位」；反之为「不当位」「不得位」。</li><li>本卦/变卦：依动爻翻变而得。解读时本卦主「体」，变卦示「用」。</li></ul><h3 id="变卦判读-按动爻条数" tabindex="-1">变卦判读（按动爻条数）： <a class="header-anchor" href="#变卦判读-按动爻条数" aria-label="Permalink to “变卦判读（按动爻条数）：”">​</a></h3><ul><li>一爻变：以本卦该动爻之爻辞为主。</li><li>两爻变：以本卦两条动爻之爻辞为主，以上者为主。</li><li>三爻变：以本卦与变卦之卦辞对读（本为「贞」/体，变为「悔」/用）。</li><li>四爻变：以变卦中两条「不变爻」之爻辞为主，以下者为主。</li><li>五爻变：以变卦中唯一「不变爻」之爻辞为主。</li><li>六爻变：以变卦之卦辞为主；干、坤两卦则读「用九」「用六」。</li><li>文本来源：本 app 收录《周易》卦辞、爻辞与象传的中/英版本，并提供繁简切换。</li></ul>',4)])])}const m=a(r,[["render",s]]);export{h as __pageData,m as default};
